  'How far the knees travel depends on your limb lengths and ankle mobility — long thighs usually mean more forward knee travel.':
    'To, jak daleko idą kolana, zależy od długości kończyn i mobilności kostek — długie uda zwykle oznaczają większe wysunięcie kolan.',
  'How is my bench progressing?': 'Jak mi idzie ławka?',
  'How is my injury?': 'Co z moją kontuzją?',
  'How is my {1} going?': 'Jak mi idzie {1}?',
  'How long do I actually rest?': 'Ile naprawdę odpoczywam?',
  'How long should I rest between sets?': 'Ile odpoczywać między seriami?',
  'How long should I rest?': 'Ile odpoczywać?',
  'How long should a workout be?': 'Ile powinien trwać trening?',
  'How many calories do I need?': 'Ile kalorii potrzebuję?',
