    'Strefa {1} ≈ nadal mówisz pełnymi zdaniami (~{2}–{3}% tętna maks.).',
  'Zooming out shows trends that single sessions hide — consistency, which lifts get attention and which get skipped.':
    'Szerszy widok pokazuje trendy, które pojedyncze treningi ukrywają — regularność, które ćwiczenia dostają uwagę, a które są pomijane.',
