  '{1} hours.': '{1} godz.',
  '{1} is one of your staples — you’ve done it {2} times, so your progress on it is the easiest to track.':
    '{1} to jedno z twoich podstawowych ćwiczeń — zrobiłeś je {2} razy, więc postęp w nim najłatwiej śledzić.',
  '{1} is the one lagging.': 'Odstaje: {1}.',
  '{1} is the top pick for that muscle with the kit at your gym.':
    '{1} to najlepszy wybór na ten mięsień przy sprzęcie na twojej siłowni.',
  '{1} min of moderate movement a week is the health baseline.':
    '{1} min umiarkowanego ruchu tygodniowo to zdrowotne minimum.',
  '{1} minutes of easy cardio, then {2}–{3} ramp-up sets on your first lift (~{4}%, {5}%, {6}%).':
    '{1} minut spokojnego cardio, potem {2}–{3} serie wstępujące w pierwszym ćwiczeniu (~{4}%, {5}%, {6}%).',
  '{1} minutes.': '{1} min.',
  '{1} minutes: {2} big lifts, {3} hard sets each, pair them as supersets, {4}–{5} s rest.':
    '{1} minut: {2} duże boje, po {3} ciężkie serie, połącz je w superserie, {4}–{5} s przerwy.',
  '{1} of the last {2} weeks had {3}+ sessions.':
    '{1} z ostatnich {2} tygodni miało {3}+ treningów.',
