    '{1} na gryfie {2} kg: na stronę {3} + {4} + {5}.',
  '{1} on a {2} kg bar: per side {3} + {4}.': '{1} na gryfie {2} kg: na stronę {3} + {4}.',
  '{1} sessions in the log and you still need a speech?':
    '{1} treningów w dzienniku, a ty dalej potrzebujesz przemowy?',
  '{1} sessions logged since {2}/{3}/{4}.': 'Zapisane treningi od {2}.{3}.{4}: {1}.',
