  '{1} sessions logged.': 'Zapisane treningi: {1}.',
  '{1} stalled at the same top weight {2} sessions running — a small back-off lets you build past it.':
    '{1} stoi na tym samym najwyższym ciężarze od {2} treningów — mały krok w tył pozwoli ci to przebić.',
  '{1} swings every minute for {2} minutes builds work capacity without much joint stress.':
    '{1} swingów co minutę przez {2} minut buduje wydolność bez dużego obciążenia stawów.',
  '{1} weeks: {2} sessions (before: {3}), {4} records; stuck: {5}, {6}.':
    '{1} tyg.: {2} treningów (wcześniej: {3}), rekordy: {4}; w stagnacji: {5}, {6}.',
  "{1} workouts in your log — I've read them.":
    '{1} treningów w twoim dzienniku — przeczytałem je.',
  '{1} {2} × {3} — {4}× bodyweight.': '{1} {2} × {3} — {4}× masa ciała.',
  '{1} × {2} at {3}%) cost working-set performance.':
    '{1} × {2} na {3}%) obniżają wyniki w seriach roboczych.',
  '{1} × {2} ≈ {3} for one rep (an estimate — the more reps, the rougher it gets).':
    '{1} × {2} ≈ {3} na jedno powtórzenie (szacunek — im więcej powtórzeń, tym mniej dokładny).',
  '{1} × {2}–{3}, add weight once you hit the top of the range on every set.':
    '{1} × {2}–{3}, dodaj ciężar, gdy dojdziesz do górnej granicy zakresu we wszystkich seriach.',
  "{1} — what your log shows: you did it {2}× in the last {3} weeks vs {4}× the {5} before; the same {6} for {7} sessions — the load hasn't been nudged.":
    '{1} — co pokazuje twój dziennik: robiłeś to {2}× w ostatnich {3} tyg. vs {4}× w {5} wcześniej; ten sam ciężar {6} od {7} treningów — obciążenie ani drgnęło.',
  '{1} — {2}.': '{1} — {2}.',
